",\n      \"chapterId\": \"li-ji_ch-41\",\n      \"passageId\": \"li-ji_ch-41_p-18\",\n      \"order\": 3,\n      \"canonicalText\": \"寬裕者，仁之作也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-41_p-18_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-41\",\n      \"passageId\": \"li-ji_ch-41_p-18\",\n      \"order\": 4,\n      \"canonicalText\": \"孫接者，仁之能也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-41_p-18_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-41\",\n      \"passageId\": \"li-ji_ch-41_p-18\",\n      \"order\": 5,\n      \"canonicalText\": \"禮節者，仁之貌也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-41_p-18_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-41\",\n      \"passageId\": \"li-ji_ch-41_p-18\",\n      \"order\": 6,\n      \"canonicalText\": \"言談者，仁之文也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-41_p-18_s-7\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-41\",\n      \"passageId\": \"li-ji_ch-41_p-18\",\n      \"order\": 7,\n      \"canonicalText\": \"歌樂者，仁之和也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-41_p-18_s-8\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-41\",\n      \"passageId\": \"li-ji_ch-41_p-18\",\n      \"order\": 8,\n      \"canonicalText\": \"分散者，仁之施也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-41_p-18_s-9\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-41\",\n      \"passageId\": \"li-ji_ch-41_p-18\",\n      \"order\": 9,\n      \"canonicalText\": \"儒皆兼此而有之，猶且不敢言仁也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-41_p-18_s-10\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-41\",\n      \"passageId\": \"li-ji_ch-41_p-18\",\n      \"order\": 10,\n      \"canonicalText\": \"其尊讓有如此者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-41_p-19_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-41\",\n      \"passageId\": \"li-ji_ch-41_p-19\",\n      \"order\": 1,\n      \"canonicalText\": \"儒有不隕獲於貧賤，不充詘於富貴，不慁君王，不累長上，不閔有司，故曰儒。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-41_p-19_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-41\",\n      \"passageId\": \"li-ji_ch-41_p-19\",\n      \"order\": 2,\n      \"canonicalText\": \"今眾人之命儒也妄，常以儒相詬病。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-41_p-19_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-41\",\n      \"passageId\": \"li-ji_ch-41_p-19\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-41_p-20_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-41\",\n      \"passageId\": \"li-ji_ch-41_p-20\",\n      \"order\": 1,\n      \"canonicalText\": \"孔子至舍，哀公館之，聞此言也，言加信，行加義：「終沒吾世，不敢以儒為戲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-41_p-20_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-41\",\n      \"passageId\": \"li-ji_ch-41_p-20\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
